public class ShippingCostRules {

    public static double costFor(double weightKg, String zone, boolean express) {
        if (weightKg <= 0 || weightKg > 30.0) {
            return -1.0;
        }
        if (zone == null) {
            return -1.0;
        }
        double base;
        if (zone.equals("domestic")) {
            base = 5.0;
        } else if (zone.equals("regional")) {
            base = 8.0;
        } else if (zone.equals("international")) {
            base = 15.0;
        } else {
            return -1.0;
        }
        if (zone.equals("domestic") && !express && weightKg <= 1.0) {
            return 0.0;
        }
        double total = base;
        if (weightKg > 2.0) {
            total += 1.5 * Math.ceil(weightKg - 2.0);
        }
        if (express) {
            total = total * 2;
        }
        return total;
    }
}
